CREATE ROLE anon NOLOGIN;CREATE ROLE authenticated NOLOGIN;CREATE ROLE service_role NOLOGIN;
CREATE SCHEMA auth;CREATE FUNCTION auth.uid()RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
CREATE FUNCTION public.ca_assert_self(p uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$BEGIN IF auth.uid() IS DISTINCT FROM p THEN RAISE EXCEPTION 'self' USING ERRCODE='42501';END IF;END$$;
CREATE TABLE clubs(id uuid primary key,name text,lifecycle_status text,asset text);CREATE TABLE club_members(club_id uuid,user_id uuid,status text);
CREATE FUNCTION public.ca_assert_player_stats_club(p_user uuid,p_club uuid,p_asset text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$BEGIN PERFORM ca_assert_self(p_user);IF NOT EXISTS(SELECT 1 FROM club_members m JOIN clubs c ON c.id=m.club_id WHERE m.user_id=p_user AND m.club_id=p_club AND m.status IN('active','approved') AND coalesce(c.lifecycle_status,'active')<>'retired' AND c.asset=p_asset)THEN RAISE EXCEPTION 'club' USING ERRCODE='42501';END IF;END$$;
CREATE FUNCTION public.ca_stats_calendar_bounds(p_days integer,p_tz text,p_now timestamptz DEFAULT now())RETURNS TABLE(range_days integer,range_tz text,from_at timestamptz,to_at timestamptz)LANGUAGE sql STABLE AS $$SELECT p_days,p_tz,CASE WHEN p_days IS NULL THEN NULL ELSE now()-make_interval(days=>p_days)END,CASE WHEN p_days IS NULL THEN NULL ELSE now()+interval '1 second' END$$;
CREATE TABLE tournaments(id uuid primary key,club_id uuid);
CREATE TABLE wallet_transactions(id uuid primary key,user_id uuid,related_entity_id uuid,type text,category text,amount numeric,balance_after numeric,description text,created_at timestamptz);
CREATE TABLE rakeback_periods(id uuid primary key,user_id uuid,club_id uuid,period_start timestamptz,period_end timestamptz,rake_generated numeric,rakeback_rate numeric,rakeback_amount numeric,rakeback_earned numeric,status text,paid_at timestamptz,deferred_reason text,deferred_at timestamptz,defer_count integer);
CREATE TABLE rakeback_period_payouts(id uuid primary key,rakeback_period_id uuid,club_id uuid,user_id uuid,payout_amount numeric,currency text,status text,paid_at timestamptz,wallet_transaction_id uuid,failure_reason text,created_at timestamptz);
GRANT USAGE ON SCHEMA public,auth TO authenticated;GRANT EXECUTE ON FUNCTION auth.uid(),public.ca_assert_self(uuid),public.ca_assert_player_stats_club(uuid,uuid,text),public.ca_stats_calendar_bounds(integer,text,timestamptz) TO authenticated,service_role;
